package com.student.controller;
import com.student.dao.*; import com.student.model.Mark; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
public class MarksServlet extends HttpServlet{private final StudentDAO students=new StudentDAO();private final CourseDAO courses=new CourseDAO();private final MarkDAO marks=new MarkDAO();protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{load(req);req.getRequestDispatcher("/marks.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{if(!Auth.loggedIn(req)){Auth.redirectLogin(resp);return;}try{double value=Double.parseDouble(req.getParameter("marks"));double max=Double.parseDouble(req.getParameter("maxMarks"));if(value<0||max<=0||value>max)throw new IllegalArgumentException();Mark m=new Mark();m.setStudentId(Integer.parseInt(req.getParameter("studentId")));m.setCourseId(Integer.parseInt(req.getParameter("courseId")));m.setMarks(value);m.setMaxMarks(max);m.setRemarks(req.getParameter("remarks"));marks.upsert(m);resp.sendRedirect("marks?success=1");}catch(Exception e){req.setAttribute("error","Invalid marks. Enter a value between 0 and the maximum marks.");try{load(req);}catch(Exception ignored){}req.getRequestDispatcher("/marks.jsp").forward(req,resp);}}private void load(HttpServletRequest req)throws Exception{req.setAttribute("students",students.findAll());req.setAttribute("courses",courses.findActiveCourses());req.setAttribute("marks",marks.findAll());}}
